{"settings":"{
	"workbench.iconTheme": "vscode-icons",
	"workbench.tree.indent": 12,
	"workbench.activityBar.location": "hidden",
	"workbench.editor.showTabs": "single",
	"workbench.startupEditor": "none",
	"workbench.tips.enabled": false,
	"workbench.statusBar.visible": false,
	"workbench.tree.renderIndentGuides": "none",
	"workbench.editor.editorActionsLocation": "hidden",
	"workbench.editor.showIcons": false,
	"workbench.editor.highlightModifiedTabs": true,
	"workbench.editor.labelFormat": "short",
	"workbench.editor.tabSizing": "shrink",
	"workbench.editor.decorations.colors": true,
	"workbench.editor.decorations.badges": true,

	// Editor settings
	"breadcrumbs.enabled": false,
	"editor.linkedEditing": true,
	"editor.cursorBlinking": "phase",
	"editor.minimap.enabled": false,
	"editor.fontFamily": "FiraCode Nerd Font",
	"editor.scrollbar.horizontal": "hidden",
	"editor.scrollbar.verticalScrollbarSize": 8,
	"editor.wordWrap": "on",
	"editor.cursorWidth": 3,
	"editor.formatOnSave": true,
	"editor.formatOnPaste": true,
	"editor.fontSize": 15,

	// Terminal settings
	"terminal.integrated.env.windows": {},
	"terminal.integrated.fontFamily": "FiraCode Nerd Font",
	"terminal.integrated.enableMultiLinePasteWarning": "never",
	"terminal.integrated.env.linux": {},

	// Explorer settings
	"explorer.confirmDelete": false,
	"explorer.confirmDragAndDrop": false,
	"explorer.compactFolders": false,
	"explorer.fileNesting.patterns": {
		"*.ts": "${capture}.js",
		"*.js": "${capture}.js.map, ${capture}.min.js, ${capture}.d.ts",
		"*.jsx": "${capture}.js",
		"*.tsx": "${capture}.ts",
		"tsconfig.json": "tsconfig.*.json",
		"package.json": "package-lock.json, yarn.lock, pnpm-lock.yaml, bun.lockb",
		"*.sqlite": "${capture}.${extname}-*",
		"*.db": "${capture}.${extname}-*",
		"*.sqlite3": "${capture}.${extname}-*",
		"*.db3": "${capture}.${extname}-*",
		"*.sdb": "${capture}.${extname}-*",
		"*.s3db": "${capture}.${extname}-*"
	},

	// Search settings
	"search.useIgnoreFiles": false,
	"search.exclude": {
		"**/vendor/{[^l],?[^ai]}*": true,
		"**/public/{[^i],?[^n]}*": true,
		"**/node_modules": true,
		"**/dist": true,
		"**/_ide_helper.php": true,
		"**/composer.lock": true,
		"**/package-lock.json": true,
		"storage": true,
		".phpunit.result.cache": true
	},

	// Prettier settings
	"prettier.jsxSingleQuote": true,
	"prettier.singleQuote": true,
	"prettier.enableDebugLogs": true,
	"prettier.useTabs": true,

	// Git settings
	"git.openRepositoryInParentFolders": "always",
	"git.autofetch": true,
	"git.confirmSync": false,

	// GitLens settings
	"gitlens.gitCommands.skipConfirmations": [
		"fetch:command",
		"stash-push:command",
		"switch:command"
	],
	"gitlens.launchpad.indicator.enabled": false,

	// Language-specific settings
	"[javascriptreact]": {
		"editor.defaultFormatter": "esbenp.prettier-vscode"
	},
	"[css]": {
		"editor.defaultFormatter": "esbenp.prettier-vscode"
	},
	"[html]": {
		"editor.defaultFormatter": "vscode.html-language-features"
	},
	"[jsonc]": {
		"editor.defaultFormatter": "esbenp.prettier-vscode"
	},
	"[javascript]": {
		"editor.defaultFormatter": "esbenp.prettier-vscode"
	},
	"[typescriptreact]": {
		"editor.defaultFormatter": "esbenp.prettier-vscode"
	},
	"[typescript]": {
		"editor.defaultFormatter": "esbenp.prettier-vscode"
	},
	"[markdown]": {
		"editor.defaultFormatter": "esbenp.prettier-vscode"
	},

	// Other settings
	"tailwindCSS.emmetCompletions": true,
	"reactSnippets.settings.importReactOnTop": false,
	"reactSnippets.settings.prettierEnabled": true,
	"diffEditor.codeLens": true,
	"liveServer.settings.donotShowInfoMsg": true,
	"github.copilot.editor.enableAutoCompletions": true,
	"typescript.updateImportsOnFileMove.enabled": "always",
	"python.analysis.autoImportCompletions": true,
	"window.menuBarVisibility": "compact",
	"workbench.sideBar.location": "right",
	"kotlin.languageServer.enabled": false,
	"kotlin.debugAdapter.enabled": false,
	"react-native-tools.showUserTips": false,
	"[json]": {
		"editor.defaultFormatter": "esbenp.prettier-vscode"
	},
	"[php]": {
		"editor.defaultFormatter": "DEVSENSE.phptools-vscode"
	},
	"vsicons.dontShowNewVersionMessage": true,
	"javascript.updateImportsOnFileMove.enabled": "always",
	"workbench.colorTheme": "Atom One Dark",
	"workbench.editorAssociations": {
		"*.copilotmd": "vscode.markdown.preview.editor",
		"*.db": "default"
	},
	"redhat.telemetry.enabled": false,
	"terminal.integrated.profiles.linux": {
		"bash": {
			"path": "bash",
			"icon": "terminal-bash"
		},
		"zsh": {
			"path": "zsh"
		},
		"fish": {
			"path": "fish"
		},
		"tmux": {
			"path": "tmux",
			"icon": "terminal-tmux"
		},
		"pwsh": {
			"path": "pwsh",
			"icon": "terminal-powershell"
		},
		"bash (2)": {
			"path": "/usr/bin/bash"
		}
	},
	"terminal.integrated.defaultProfile.linux": "zsh",
	"chat.instructionsFilesLocations": {
		".github/instructions": true,
		"/tmp/postman-http-request-post-response.instructions.md": true,
		"/tmp/postman-http-request-pre-request.instructions.md": true,
		"/tmp/postman-collections-post-response.instructions.md": true,
		"/tmp/postman-collections-pre-request.instructions.md": true,
		"/tmp/postman-folder-post-response.instructions.md": true,
		"/tmp/postman-folder-pre-request.instructions.md": true
	},
	"github.copilot.nextEditSuggestions.enabled": true,
	"vscode-blur-linux.opacity": 30,
	"workbench.preferredDarkColorTheme": "Red",
	"files.autoSave": "afterDelay",
	"cSpell.userWords": ["ecoderum"]
}"}
